    selectedIconColor = CbmPalette.HiVis, selectedTextColor = Color.White,
    unselectedIconColor = CbmPalette.Steel300, unselectedTextColor = CbmPalette.Steel300,
    indicatorColor = CbmPalette.Steel700,
)

