            },
            dismissButton = { CbmSmallAction("Cancel", { confirmSubmit = false }, filled = false) },
        )
    }
    info?.let {
        AlertDialog(onDismissRequest = { info = null }, confirmButton = { CbmSmallAction("OK", { info = null }) }, text = { Text(it) })
    }
