@Composable
private fun ChatBubble(msg: ChatMsg, state: FmState) {
    if (msg.fromAgent) {
        Column(Modifier.fillMaxWidth().padding(end = 32.dp)) {
            Text("AGENT · WF3", style = LocalTechStyles.current.stencil, color = CbmPalette.Teal)
